cards.back:
```python
from abc import ABC, abstractmethod

class PaymentMethod(ABC):
    @abstractmethod
    def process(self, amount):
        pass

class CreditCardPayment(PaymentMethod):
    def process(self, amount):
        print(f"Processing CreditCard payment of ${amount}")

class PayPalPayment(PaymentMethod):
    def process(self, amount):
        print(f"Processing PayPal payment of ${amount}")

# New payment method can be added without changing existing code
class StripePayment(PaymentMethod):
    def process(self, amount):
        print(f"Processing Stripe payment of ${amount}")

class PaymentProcessor:
    def process_payment(self, payment_method: PaymentMethod, amount):
        payment_method.process(amount)

# Usage:
processor = PaymentProcessor()
processor.process_payment(CreditCardPayment(), 100)
processor.process_payment(PayPalPayment(), 50)
processor.process_payment(StripePayment(), 200) # No change to PaymentProcessor needed
```
This adheres to OCP because new payment methods can be added by creating new `PaymentMethod` subclasses without modifying the `PaymentProcessor` class or existing payment method implementations.
